<?php require_once 'includes/db.php';require_once 'includes/functions.php';$id=(int)($_GET['id']??0);$s=$conn->prepare("SELECT * FROM products WHERE id=? AND active=1");$s->bind_param('i',$id);$s->execute();$p=$s->get_result()->fetch_assoc();if(!$p){http_response_code(404);$title='Not found';include 'includes/header.php';echo '<div class="empty"><h2>Product not found</h2><a href="index.php">Back to shop</a></div>';include 'includes/footer.php';exit;}$title=$p['name'];include 'includes/header.php';?>
<section class="detail"><img src="<?=e($p['image_url'])?>" onerror="this.src='assets/product.svg'" alt="<?=e($p['name'])?>"><div><small><?=e($p['category'])?></small><h1><?=e($p['name'])?></h1><h2>₹<?=number_format($p['price'],2)?></h2><p><?=nl2br(e($p['description']))?></p><p class="muted"><?= (int)$p['stock']?> in stock</p><?php if($p['stock']>0):?><form method="post" action="cart.php" class="buy"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="number" name="qty" min="1" max="<?=$p['stock']?>" value="1"><button class="btn dark">Add to cart</button></form><?php endif;?><a href="index.php">← Back to shop</a></div></section><?php include 'includes/footer.php';?>